fn read_db() -> HashMap<String, u64> {
    let db_path = get_db_path();
    if !db_path.exists() {
        return HashMap::new();
    }

    let file = File::open(&db_path).unwrap_or_else(|_| panic!("Could not open database file: {}", db_path.display()));
    let reader = BufReader::new(file);

    let mut db = HashMap::new();
    for line in reader.lines() {
        let line = line.unwrap_or_default();
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() >= 2 {
            let path = parts[0].to_string();
            let score: u64 = parts[1].parse().unwrap_or(0);
            db.insert(path, score);
        }
    }
    db
}

fn write_db(db: &HashMap<String, u64>) {
    let db_path = get_db_path();
    let parent = db_path.parent().unwrap_or_else(|| Path::new("."));
    fs::create_dir_all(parent).ok();

    let mut file = File::create(&db_path).unwrap_or_else(|_| {
        panic!("Could not create database file: {}", db_path.display());
    });
```

