use std::env;
use std::fs::{self, File};
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process;

const VERSION: &str = "0.9.9";

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() > 1 && (args[1] == "-h" || args[1] == "--help") {
        print_help();
        process::exit(0);
    }

    if args.len() > 1 && (args[1] == "-V" || args[1] == "--version") {
        println!("zoxide {}", VERSION);
        process::exit(0);
    }

    if args.is_empty() || args.len() == 1 {
        print_help();
        process::exit(0);
    }

    let command = &args[1];
    let args: Vec<String> = args[2..].to_vec();

    match command.as_str() {
        "add" => add(&args),
        "edit" => edit(&args),
        "import" => import(&args),
        "init" => init(&args),
        "query" => query(&args),
        "remove" => remove(&args),
        _ => {
            eprintln!("zoxide: invalid command '{}'", command);
            print_help();
            process::exit(1);
        }
    }
}

fn print_help() {
    println!("zoxide {}", VERSION);
    println!("Ajeet D'Souza <98ajeet@gmail.com>");
    println!("https://github.com/ajeetdsouza/zoxide");
    println!();
    println!("A smarter cd command for your terminal");
    println!();
    println!("Usage:");
    println!("  executable <COMMAND>");
    println!();
    println!("Commands:");
    println!("  add     Add a new directory or increment its rank");
    println!("  edit    Edit the database");
    println!("  import  Import entries from another application");
    println!("  init    Generate shell configuration");
    println!("  query   Search for a directory in the database");
    println!("  remove  Remove a directory from the database");
    println!();
    println!("Options:");
    println!("  -h, --help     Print help");
    println!("  -V, --version  Print version");
    println!();
    println!("Environment variables:");
    println!("  _ZO_DATA_DIR          Path for zoxide data files");
    println!("  _ZO_ECHO              Print the matched directory before navigating to it when set to 1");
    println!("  _ZO_EXCLUDE_DIRS      List of directory globs to be excluded");
    println!("  _ZO_FZF_OPTS          Custom flags to pass to fzf");
    println!("  _ZO_MAXAGE            Maximum total age after which entries start getting deleted");
    println!("  _ZO_RESOLVE_SYMLINKS  Resolve symlinks when storing paths");
}

fn get_data_dir() -> PathBuf {
    if let Ok(data_dir) = env::var("_ZO_DATA_DIR") {
        return PathBuf::from(data_dir);
    }

    if cfg!(target_os = "macos") {
        return PathBuf::from(env::var("HOME").unwrap_or_else(|_| "/home".to_string()))
            .join("Library/Application Support/zoxide");
    }

    if cfg!(target_os = "windows") {
        if let Ok(local_app_data) = env::var("LOCALAPPDATA") {
            return PathBuf::from(local_app_data).join("zoxide");
        }
    }

    if let Ok(xdg_data_home) = env::var("XDG_DATA_HOME") {
        return PathBuf::from(xdg_data_home).join("zoxide");
    }

    PathBuf::from(env::var("HOME").unwrap_or_else(|_| "/home".to_string()))
        .join(".local/share/zoxide")
}

fn get_db_path() -> PathBuf {
    get_data_dir().join("db.zoxide")
}

fn get_excluded_dirs() -> Vec<String> {
    if let Ok(exclude) = env::var("_ZO_EXCLUDE_DIRS") {
        if exclude.is_empty() {
            return vec!["$HOME".to_string()];
        }
        return exclude.split(':').map(|s| s.to_string()).collect();
    }
    vec!["$HOME".to_string()]
}

fn get_max_age() -> usize {
    env::var("_ZO_MAXAGE")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(10000)
}

fn get_resolve_symlinks() -> bool {
    env::var("_ZO_RESOLVE_SYMLINKS")
        .ok()
        .and_then(|s| s.parse().ok())
        .unwrap_or(false)
}

fn get_fzf_opts() -> String {
    env::var("_ZO_FZF_OPTS").unwrap_or_default()
}

fn read_db() -> HashMap<String, u64> {
    let db_path = get_db_path();
    if !db_path.exists() {
        return HashMap::new();
    }

    let file = File::open(&db_path).unwrap_or_else(|_| panic!("Could not open database file: {}", db_path.display()));
    let reader = BufReader::new(file);

    let mut db = HashMap::new();
    for line in reader.lines() {
        let line = line.unwrap_or_default();
        let parts: Vec<&str> = line.split_whitespace().collect();
        if parts.len() >= 2 {
            let path = parts[0].to_string();
            let score: u64 = parts[1].parse().unwrap_or(0);
            db.insert(path, score);
        }
    }
    db
}

fn write_db(db: &HashMap<String, u64>) {
    let db_path = get_db_path();
    let parent = db_path.parent().unwrap_or_else(|| Path::new("."));
    fs::create_dir_all(parent).ok();

    let mut file = File::create(&db_path).unwrap_or_else(|_| {
        panic!("Could not create database file: {}", db_path.display());
    });

    for (path, score) in db {
        writeln!(file, "{} {}", path, score).ok();
    }
}

fn add(args: &[String]) {
    let path = if args.is_empty() {
        env::current_dir().unwrap_or_else(|_| PathBuf::from("."))
    } else {
        PathBuf::from(&args[0])
    };

    let path_str = path.to_string_lossy().to_string();

    let excluded = get_excluded_dirs();
    for exclude in &excluded {
        if path_str.contains(exclude) {
            return;
        }
    }

    let mut db = read_db();
    let score = db.get(&path_str).copied().unwrap_or(0) + 1;
    db.insert(path_str, score);
    write_db(&db);
}

fn query(args: &[String]) {
    let query = if args.is_empty() {
        String::new()
    } else {
        args.join(" ")
    };

    let db = read_db();

    if query.is_empty() {
        if db.is_empty() {
            eprintln!("zoxide: no entries in database");
            process::exit(1);
        }
        let mut entries: Vec<_> = db.iter().collect();
        entries.sort_by(|a, b| b.1.cmp(a.1));
        for (path, _) in entries {
            println!("{}", path);
        }
        return;
    }

    let query_lower = query.to_lowercase();
    let mut matches: Vec<_> = db.iter()
        .filter(|(path, _)| {
            let path_lower = path.to_lowercase();
            path_lower.contains(&query_lower)
        })
        .collect();

    matches.sort_by(|a, b| b.1.cmp(a.1));

    if matches.is_empty() {
        eprintln!("zoxide: no match found");
        process::exit(1);
    }

    for (path, _) in matches {
        println!("{}", path);
    }
}

fn remove(args: &[String]) {
    if args.is_empty() {
        eprintln!("zoxide: no path specified");
        process::exit(1);
    }

    let path = PathBuf::from(&args[0]);
    let path_str = path.to_string_lossy().to_string();

    let mut db = read_db();
    db.remove(&path_str);
    write_db(&db);
}

fn edit(_args: &[String]) {
    let fzf_opts = get_fzf_opts();

    let db = read_db();
    if db.is_empty() {
        eprintln!("zoxide: no entries in database");
        process::exit(1);
    }

    let _entries: Vec<_> = db.iter()
        .map(|(path, score)| format!("{} {}", path, score))
        .collect();

    let fzf_cmd = if fzf_opts.is_empty() {
        String::from("fzf --height 40% --reverse --bind 'enter:execute(echo {} | xargs -I {} zoxide remove {})_and_exit' --preview 'zoxide query {}' --preview-window right:50%")
    } else {
        let mut cmd = String::from("fzf --height 40% --reverse --bind 'enter:execute(echo {} | xargs -I {} zoxide remove {})_and_exit' --preview 'zoxide query {}' --preview-window right:50%");
        cmd.push_str(&format!(" {}", fzf_opts));
        cmd
    };

    let fzf_cmd = format!("echo {} | {}", fzf_opts, fzf_cmd);

    let output = std::process::Command::new("sh")
        .arg("-c")
        .arg(&fzf_cmd)
        .output();

    if let Ok(out) = output {
        if !out.status.success() {
            return;
        }
        let selected = String::from_utf8_lossy(&out.stdout).trim().to_string();
        if !selected.is_empty() {
            let parts: Vec<&str> = selected.split_whitespace().collect();
            if parts.len() >= 2 {
                let path = parts[0].to_string();
                let score: u64 = parts[1].parse().unwrap_or(0);
                let mut db = read_db();
                db.insert(path, score);
                write_db(&db);
            }
        }
    }
}

fn import(args: &[String]) {
    if args.is_empty() {
        eprintln!("zoxide: no path specified");
        process::exit(1);
    }

    let path = PathBuf::from(&args[0]);
    if !path.exists() {
        eprintln!("zoxide: {} does not exist", path.display());
        process::exit(1);
    }

    let mut db = read_db();

    if path.is_dir() {
        let entries = fs::read_dir(&path).unwrap_or_else(|_| {
            eprintln!("zoxide: could not read directory: {}", path.display());
            process::exit(1);
        });

        for entry in entries {
            let entry = entry.unwrap_or_else(|_| {
                eprintln!("zoxide: could not read entry");
                process::exit(1);
            });
            let path_str = entry.path().to_string_lossy().to_string();
            if path_str.contains("$HOME") {
                continue;
            }
            let score = db.get(&path_str).copied().unwrap_or(0) + 1;
            db.insert(path_str, score);
        }
    } else {
        let path_str = path.to_string_lossy().to_string();
        let score = db.get(&path_str).copied().unwrap_or(0) + 1;
        db.insert(path_str, score);
    }

    write_db(&db);
}

fn init(_args: &[String]) {
    let mut output = String::new();

    output.push_str(&format!("__zoxide_zoxide_data_dir=\"{}\"\n", get_data_dir().display()));
    output.push_str(&format!("__zoxide_zoxide_exclude_dirs=\"{}\"\n", get_excluded_dirs().join(":")));
    output.push_str(&format!("__zoxide_zoxide_fzf_opts=\"{}\"\n", get_fzf_opts()));
    output.push_str(&format!("__zoxide_zoxide_maxage={}\n", get_max_age()));
    output.push_str(&format!("__zoxide_zoxide_resolve_symlinks={}\n", if get_resolve_symlinks() { "1" } else { "0" }));
    output.push_str(&format!("__zoxide_zoxide_echo={}\n", if env::var("_ZO_ECHO").unwrap_or_default() == "1" { "1" } else { "0" }));

    println!("{}", output);
}

